import React, { useEffect } from "react";
import { useFormik } from "formik";
import { useHistory, Link } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import * as Yup from "yup";
import { loginUserAction } from "../../redux/slices/users/usersSlices";
import DisabledButton from "../../components/DisableButton";
import "../../App.css";

// Form validations
const formSchema = Yup.object({
  email: Yup.string().required("Email is required").email("Enter a valid email"),
  password: Yup.string().required("Password is required"),
});

const Login = () => {
  const history = useHistory();
  const dispatch = useDispatch();

  const user = useSelector((state) => state?.users);
  const { userAppErr, userServerErr, userLoading, userAuth } = user;

  const formik = useFormik({
    initialValues: {
      email: "",
      password: "",
    },
    onSubmit: (values) => {
      dispatch(loginUserAction(values));
    },
    validationSchema: formSchema,
  });

  useEffect(() => {
    if (userAuth) {
      if (userAuth?.isAdmin) history.push("/dashboard");
      else history.push("/profile");
    }
  }, [userAuth, history]);

  return (
    <section className="app-container auth-page-bg">
      <div className="auth-card">
        <div className="text-center">
          <h2 className="auth-title">Welcome Back</h2>
          <p className="auth-subtitle">Login to continue managing your finances</p>
          <div className="auth-divider" />
        </div>

        {(userAppErr || userServerErr) && (
          <div className="alert alert-danger" role="alert">
            {userServerErr} {userAppErr}
          </div>
        )}

        <form onSubmit={formik.handleSubmit}>
          <div className="mb-3">
            <label className="form-label fw-semibold">Email</label>
            <input
              value={formik.values.email}
              onChange={formik.handleChange("email")}
              onBlur={formik.handleBlur("email")}
              className="form-control"
              type="email"
              name="email"
              placeholder="Enter your email"
            />
            <div className="text-danger mt-1 small">
              {formik.touched.email && formik.errors.email}
            </div>
          </div>

          <div className="mb-3">
            <label className="form-label fw-semibold">Password</label>
            <input
              value={formik.values.password}
              onChange={formik.handleChange("password")}
              onBlur={formik.handleBlur("password")}
              className="form-control"
              type="password"
              name="password"
              placeholder="Enter your password"
            />
            <div className="text-danger mt-1 small">
              {formik.touched.password && formik.errors.password}
            </div>
          </div>

          {userLoading ? (
            <DisabledButton />
          ) : (
            <button type="submit" className="btn btn-primary w-100 mt-2">
              Login
            </button>
          )}

          <p className="mt-3 text-center mb-0">
            Don&apos;t have an account?{" "}
            <Link to="/register" className="auth-link">
              Create account
            </Link>
          </p>
        </form>
      </div>
    </section>
  );
};

export default Login;
